input.command:
$failures = [System.Collections.Generic.List[string]]::new()
foreach ($f in @('note.md','report.md','verify.log')) {
    if (-not (Test-Path -LiteralPath $f -PathType Leaf)) { $failures.Add("MISSING:$f") }
}
$noteBytes = [System.IO.File]::ReadAllBytes((Join-Path (Get-Location) 'note.md'))
$noteRaw = [System.Text.Encoding]::UTF8.GetString($noteBytes)
if ($noteRaw -cne '# hello') { $failures.Add('NOTE_CONTENT_MISMATCH') }
$reportRaw = Get-Content -LiteralPath 'report.md' -Raw -Encoding utf8
foreach ($section in @('## 1. 做了什么','## 2. 产物路径','## 3. 关键数据','## 4. 是否通过','## 5. 下一步')) {
    if (-not $reportRaw.Contains($section)) { $failures.Add("MISSING_SECTION:$section") }
}
$externalLinks = ([regex]::Matches($noteRaw + $reportRaw, 'https?://')).Count
if ($externalLinks -ne 0) { $failures.Add("EXTERNAL_LINKS:$externalLinks") }
"NOTE_BYTES=$($noteBytes.Length)"
"NOTE_LINES=$((Get-Content -LiteralPath 'note.md' -Encoding utf8).Count)"
"NOTE_EXACT_MATCH=$($noteRaw -ceq '# hello')"
"NOTE_SHA256=$((Get-FileHash -Algorithm SHA256 -LiteralPath 'note.md').Hash)"
$reportItem = Get-Item -LiteralPath 'report.md'
"REPORT_BYTES=$($reportItem.Length)"
"REPORT_LINES=$((Get-Content -LiteralPath 'report.md' -Encoding utf8).Count)"
"REPORT_SHA256=$((Get-FileHash -Algorithm SHA256 -LiteralPath 'report.md').Hash)"
"REPORT_SECTIONS_OK=$(-not ($failures -match 'MISSING_SECTION'))"
"EXTERNAL_LINKS=$externalLinks"
"FINAL_RESULT=$(if ($failures.Count -eq 0) { 'PASS' } else { 'FAIL: ' + ($failures -join ',') })"
if ($failures.Count -ne 0) { exit 1 }
"FINAL_EXIT_CODE=0"
exit 0
